var validStatesByMode = {
  'production': ['running', 'running-slow', 'unknown'],
  'disabled': ['faulted', 'e-stopped', 'blocked', 'starved', 'offline'],
  'setup': ['changeover', 'warmup', 'cleaning'],
  'cleaning': ['cleaning', 'offline'],
  'idle': ['stopped', 'offline'],
  'maintenance': ['maintenance', 'offline'],
  'no-schedule': ['offline'],
  'engineering': ['stopped', 'offline', 'changeover']
};

var defaultStateByMode = {
  'production': 'running',
  'disabled': 'faulted',
  'setup': 'changeover',
  'cleaning': 'cleaning',
  'idle': 'stopped',
  'maintenance': 'maintenance',
  'no-schedule': 'offline',
  'engineering': 'stopped'
};

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function getValidStatesForMode(modeId) {
  var validStateIds = validStatesByMode[modeId] || [];
  return validStateIds.map(function(sid) { return stateById[sid]; }).filter(function(s) { return s; });
}

function selectValidStateForMode(mode) {
  if (!mode) return states[0];
  
  var validStates = getValidStatesForMode(mode.id);
  
  if (validStates.length === 0) {
    var defaultSid = defaultStateByMode[mode.id];
    return stateById[defaultSid] || states[0];
  }
  
  if (mode.id === 'production') {
    var producingStates = validStates.filter(function(s) { return s.isProducing; });
    if (producingStates.length > 0 && Math.random() < 0.85) {
      return producingStates[Math.floor(Math.random() * producingStates.length)];
    }
  }
  
  return validStates[Math.floor(Math.random() * validStates.length)];
}

function shouldChangeState(openHistory, nowMs) {
  if (!openHistory) return true;
  
  var openMoment = $moment(openHistory.occurAt);
  var elapsedMs = nowMs - openMoment.valueOf();
  var elapsedMinutes = elapsedMs / 60000;
  
  var randomMultiplier = Math.floor(Math.random() * 100) + 1;
  var requiredMinutes = randomMultiplier * 3;
  
  return elapsedMinutes >= requiredMinutes;
}

function isScheduled(wc, scheduleMap) {
  if (!wc.scheduleGroupId) return false;
  return scheduleMap[wc.scheduleGroupId] ? true : false;
}

function calculateDuration(startTimestamp, endTimestamp) {
  var startMs = $moment(startTimestamp).valueOf();
  var endMs = $moment(endTimestamp).valueOf();
  
  var durationMs = endMs - startMs;
  if (durationMs < 0) durationMs = 0;
  
  return durationMs;
}

/**
 * Calculate ISO 22400 time classification based on mode flags
 * @param {number} durationMs - Duration in milliseconds
 * @param {object} mode - Mode object with flags
 * @returns {object} { runTime, plannedDowntime, unplannedDowntime }
 */
function calculateTimeClassification(durationMs, mode) {
  var runTime = 0;
  var plannedDowntime = 0;
  var unplannedDowntime = 0;
  
  if (!mode) {
    // No mode = treat as unplanned downtime
    unplannedDowntime = durationMs;
  } else if (mode.countAsProductionTime) {
    // Production time (ISO 22400: Actual Production Time)
    runTime = durationMs;
  } else if (mode.countAsDowntime) {
    if (mode.countAsPlannedDowntime) {
      // Planned downtime (ISO 22400: Planned Downtime)
      plannedDowntime = durationMs;
    } else {
      // Unplanned downtime (ISO 22400: Unplanned Downtime)
      unplannedDowntime = durationMs;
    }
  }
  // else: mode doesn't count as production or downtime = all zeros (excluded time)
  
  return {
    runTime: runTime,
    plannedDowntime: plannedDowntime,
    unplannedDowntime: unplannedDowntime
  };
}

// ============================================================================
// INITIALIZE ARRAYS
// ============================================================================
var allHistoryToClose = [];
var allHistoryToCreate = [];
var allWorkcentersToUpdate = [];
var codeCounter = Date.now();

// Track time classification stats
var timeStats = {
  totalRunTime: 0,
  totalPlannedDowntime: 0,
  totalUnplannedDowntime: 0,
  recordsClassified: 0
};

// ============================================================================
// STEP 1: CLOSE ALL DUPLICATE OPEN HISTORY RECORDS
// ============================================================================
duplicateOpenHistory.forEach(function(hist) {
  var endMoment = $moment(nowUTCMs - 1).tz(timezone);
  var endAt = endMoment.utc().toISOString();
  
  var durationMs = calculateDuration(hist.occurAt, endAt);
  
  // Get mode for time classification
  var histMode = modeById[hist.modeId];
  var timeClass = calculateTimeClassification(durationMs, histMode);
  
  // Track stats
  timeStats.totalRunTime += timeClass.runTime;
  timeStats.totalPlannedDowntime += timeClass.plannedDowntime;
  timeStats.totalUnplannedDowntime += timeClass.unplannedDowntime;
  timeStats.recordsClassified++;
  
  allHistoryToClose.push({
    where: { id: hist.id },
    update: {
      endAt: endAt,
      duration: durationMs,
      runTime: timeClass.runTime,
      plannedDowntime: timeClass.plannedDowntime,
      unplannedDowntime: timeClass.unplannedDowntime
    }
  });
});

// ============================================================================
// STEP 2: PROCESS ALL WORKCENTERS IN ONE PASS
// ============================================================================

// Select workcenters that will change state this iteration
var changingWcs = workcenters.filter(function() { 
  return Math.random() < changeProb; 
});

var minProdCount = Math.max(1, Math.ceil(changingWcs.length * minProductionRatio));

changingWcs.forEach(function(wc, idx) {
  var openHistory = openHistoryByWc[wc.id];
  var scheduled = isScheduled(wc, currentScheduleByGroup);
  
  // --------------------------------------------------------------------------
  // UNSCHEDULED WORKCENTER LOGIC
  // --------------------------------------------------------------------------
  if (!scheduled) {
    if (openHistory && openHistory.modeId !== 'no-schedule' && noScheduleMode && offlineState) {
      var endMoment = $moment(nowUTCMs - 1).tz(timezone);
      var endAt = endMoment.utc().toISOString();
      
      var durationMs = calculateDuration(openHistory.occurAt, endAt);
      
      // Get mode for time classification
      var histMode = modeById[openHistory.modeId];
      var timeClass = calculateTimeClassification(durationMs, histMode);
      
      // Track stats
      timeStats.totalRunTime += timeClass.runTime;
      timeStats.totalPlannedDowntime += timeClass.plannedDowntime;
      timeStats.totalUnplannedDowntime += timeClass.unplannedDowntime;
      timeStats.recordsClassified++;
      
      allHistoryToClose.push({
        where: { id: openHistory.id },
        update: {
          endAt: endAt,
          duration: durationMs,
          runTime: timeClass.runTime,
          plannedDowntime: timeClass.plannedDowntime,
          unplannedDowntime: timeClass.unplannedDowntime
        }
      });
      
      codeCounter++;
      var noScheduleCode = 'WCH-' + codeCounter.toString(36).toUpperCase();
      
      allHistoryToCreate.push({
        create: {
          code: noScheduleCode,
          workcenterId: wc.id,
          occurAt: nowUTCTs,
          modeId: noScheduleMode.id,
          stateId: offlineState.id,
          eventId: null,
          scheduleId: null,
          notes: 'No active schedule defined'
        }
      });
      
      allWorkcentersToUpdate.push({
        where: { id: wc.id },
        update: {
          currentModeId: noScheduleMode.id,
          currentStateId: offlineState.id,
          currentEventId: null,
          stateChangedAt: nowUTCTs
        }
      });
    }
    return;
  }
  
  // --------------------------------------------------------------------------
  // SCHEDULED WORKCENTER LOGIC
  // --------------------------------------------------------------------------
  
  if (!shouldChangeState(openHistory, nowUTCMs)) {
    return;
  }
  
  if (openHistory) {
    var openMoment = $moment(openHistory.occurAt);
    
    if (openMoment.valueOf() >= nowUTCMs) {
      return;
    }
    
    var endMoment = $moment(nowUTCMs - 1).tz(timezone);
    var endAt = endMoment.utc().toISOString();
    
    var durationMs = calculateDuration(openHistory.occurAt, endAt);
    
    // Get mode for time classification
    var histMode = modeById[openHistory.modeId];
    var timeClass = calculateTimeClassification(durationMs, histMode);
    
    // Track stats
    timeStats.totalRunTime += timeClass.runTime;
    timeStats.totalPlannedDowntime += timeClass.plannedDowntime;
    timeStats.totalUnplannedDowntime += timeClass.unplannedDowntime;
    timeStats.recordsClassified++;
    
    allHistoryToClose.push({
      where: { id: openHistory.id },
      update: {
        endAt: endAt,
        duration: durationMs,
        runTime: timeClass.runTime,
        plannedDowntime: timeClass.plannedDowntime,
        unplannedDowntime: timeClass.unplannedDowntime
      }
    });
  }
  
  // --------------------------------------------------------------------------
  // SELECT NEW MODE AND STATE
  // --------------------------------------------------------------------------
  var forceProduction = idx < minProdCount;
  var newMode, newState;
  
  if (forceProduction) {
    var prodMode = modeById['production'];
    if (!prodMode) {
      prodMode = modes.filter(function(m) { return m.countAsProductionTime; })[0] || modes[0];
    }
    
    var validStates = getValidStatesForMode(prodMode.id);
    var producingStates = validStates.filter(function(s) { return s.isProducing; });
    
    newState = producingStates.length > 0 
      ? producingStates[Math.floor(Math.random() * producingStates.length)]
      : validStates[0] || stateById['running'] || states[0];
    
    newMode = prodMode;
    
  } else {
    var modeWeights = {
      'production': 0.60,
      'idle': 0.15,
      'setup': 0.10,
      'maintenance': 0.10,
      'no-schedule': 0.05
    };
    
    var totalWeight = 0;
    var weights = modes.map(function(m) {
      var w = modeWeights[m.id] || modeWeights[m.code] || modeWeights[m.name] || 1;
      totalWeight += w;
      return w;
    });
    
    var rand = Math.random() * totalWeight;
    newMode = modes[0];
    for (var j = 0; j < modes.length; j++) {
      rand -= weights[j];
      if (rand <= 0) {
        newMode = modes[j];
        break;
      }
    }
    
    newState = selectValidStateForMode(newMode);
  }
  
  // CRITICAL: Ensure newMode and newState are NEVER null
  if (!newMode) {
    newMode = modes[0];
    console.warn('Using fallback mode for workcenter: ' + wc.id);
  }
  if (!newState) {
    newState = states[0];
    console.warn('Using fallback state for workcenter: ' + wc.id);
  }
  
  var newEvent = (newMode && newMode.countAsDowntime && events.length > 0) 
    ? events[Math.floor(Math.random() * events.length)] 
    : null;
  
  var scheduleId = wc.scheduleGroupId 
    ? (currentScheduleByGroup[wc.scheduleGroupId] || null) 
    : null;
  
  codeCounter++;
  var newCode = 'WCH-' + codeCounter.toString(36).toUpperCase();
  
  allHistoryToCreate.push({
    create: {
      code: newCode,
      workcenterId: wc.id,
      occurAt: nowUTCTs,
      modeId: newMode.id,
      stateId: newState.id,
      eventId: newEvent ? newEvent.id : null,
      scheduleId: scheduleId,
      notes: null
    }
  });
  
  allWorkcentersToUpdate.push({
    where: { id: wc.id },
    update: {
      currentModeId: newMode.id,
      currentStateId: newState.id,
      currentEventId: newEvent ? newEvent.id : null,
      stateChangedAt: nowUTCTs
    }
  });
});

// ============================================================================
// BUILD OUTPUT BATCHES
// ============================================================================
var batches = [];

// Add close batch if needed
if (allHistoryToClose.length > 0) {
  batches.push({
    batchType: 'close',
    batchIndex: 1,
    historyToClose: allHistoryToClose,
    stats: {
      tenantTimezone: timezone,
      executedAt: nowUTCTs,
      recordsClosed: allHistoryToClose.length,
      timeClassification: {
        totalRunTimeMs: timeStats.totalRunTime,
        totalPlannedDowntimeMs: timeStats.totalPlannedDowntime,
        totalUnplannedDowntimeMs: timeStats.totalUnplannedDowntime,
        recordsClassified: timeStats.recordsClassified
      }
    }
  });
}

// Add combined create+update batch if needed
if (allHistoryToCreate.length > 0 && allWorkcentersToUpdate.length > 0) {
  batches.push({
    batchType: 'create',
    batchIndex: 2,
    historyToCreate: allHistoryToCreate,
    workcentersToUpdate: allWorkcentersToUpdate,
    stats: {
      tenantTimezone: timezone,
      executedAt: nowUTCTs,
      recordsCreated: allHistoryToCreate.length,
      workcentersUpdated: allWorkcentersToUpdate.length
    }
  });
}

// ============================================================================
// EXECUTION SUMMARY LOGGING
// ============================================================================
console.log('=============================================================');
console.log('Workcenter History State Change Processor (ISO 22400)');
console.log('=============================================================');
console.log('  Execution Time (UTC): ' + nowUTCTs);
console.log('  Tenant Timezone: ' + timezone);
console.log('  Total Workcenters: ' + workcenters.length);
console.log('  Changing Workcenters: ' + changingWcs.length);
console.log('  Records to Close: ' + allHistoryToClose.length);
console.log('  Records to Create: ' + allHistoryToCreate.length);
console.log('  Workcenters to Update: ' + allWorkcentersToUpdate.length);
console.log('─────────────────────────────────────────────────────────────');
console.log('ISO 22400 Time Classification:');
console.log('  Run Time: ' + Math.round(timeStats.totalRunTime / 1000) + 's (' + timeStats.totalRunTime + 'ms)');
console.log('  Planned Downtime: ' + Math.round(timeStats.totalPlannedDowntime / 1000) + 's (' + timeStats.totalPlannedDowntime + 'ms)');
console.log('  Unplanned Downtime: ' + Math.round(timeStats.totalUnplannedDowntime / 1000) + 's (' + timeStats.totalUnplannedDowntime + 'ms)');
console.log('  Records Classified: ' + timeStats.recordsClassified);
console.log('─────────────────────────────────────────────────────────────');
console.log('  Total Batches: ' + batches.length);
console.log('=============================================================');

return batches.length > 0 ? batches : null;

data.query:
query GetWorkcenterHistoryData {
  # Get tenant timezone setting
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        id
        defaultValue
      }
    }
  }
  
  # Get all active workcenters with schedule group assignments
  workcenter(where: { isActive: { _eq: true } }) {
    edges {
      node {
        id
        code
        name
        scheduleGroupId
        currentWorkcenterHistoryId
      }
    }
  }
  
  # Get open workcenter history records
  workcenterHistory(where: { endAt: { _isNull: true } }) {
    edges {
      node {
        id
        code
        workcenterId
        occurAt
        endAt
        modeId
        stateId
        eventId
        scheduleId
        duration
        processedInOeeHourlyAt
        runTime
        plannedDowntime
        unplannedDowntime
        notes
      }
    }
  }
  
  # Get all downtime events
  event {
    edges {
      node {
        id
        code
        name
        description
      }
    }
  }
  
  # Get all operational modes
  mode {
    edges {
      node {
        id
        code
        name
        countAsProductionTime
        countAsDowntime
        countAsPlannedDowntime
      }
    }
  }
  
  # Get all operational states
  state {
    edges {
      node {
        id
        code
        name
        isProducing
        isFault
      }
    }
  }
}

data.transform:
(
  $now := $moment();
  $workcenters := workcenter.edges.node;
  $timezone := setting.edges[0].node.defaultValue ? setting.edges[0].node.defaultValue : "UTC";
  
  /* Get unique scheduleGroupIds */
  $scheduleGroupIds := $distinct($workcenters.scheduleGroupId)[$ != null];
  
  /* Build mapping: scheduleGroupId → current active scheduleId */
  $currentScheduleByGroup := $merge($scheduleGroupIds.(
    $groupId := $;
    $currentSchedules := $scheduleGroup($groupId).getCurrentSchedules($now, $now, { "inclusive": true });
    $activeSchedule := $currentSchedules[0];
    { ($groupId): $activeSchedule.scheduleId }
  ));
  
  /* Merge with original query results and add schedule mapping */
  $merge([$, { 
    "currentScheduleByGroup": $currentScheduleByGroup,
    "tenantTimezone": $timezone
  }])
)
